const state = { view: 'overview', dashboard: null, chemicals: [], analysisId: null, analysis: null, graph: null, propertyCatalog: null, propertyX: null, propertyY: null, comparisonChemicals: [], comparisonDetails: {}, comparisonA: null, comparisonB: null, comparisonRequest: 0, results: [], liveRecords: {}, libraryFolderId: null, libraryFolders: [], currentChemical: null, pendingLibraryItem: null, assistantHistory: [], user: null };
const $ = (s) => document.querySelector(s);
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let authToken = (() => { try { return sessionStorage.getItem('chemrd_session_token') || ''; } catch (_) { return ''; } })();
const authHeaders = () => authToken ? {Authorization:`Bearer ${authToken}`} : {};
const api = async (path, options={}) => { const r = await fetch(path, {credentials:'same-origin', cache:'no-store', headers:{'Content-Type':'application/json', ...authHeaders(), ...(options.headers||{})}, ...options}); let data={}; try{ data=await r.json(); }catch(_){ data={}; } if(!r.ok){ if(r.status===401&&!path.startsWith('/api/auth')){ let sessionAlive=false; try{ const session=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store',headers:authHeaders()}); sessionAlive=session.ok; }catch(_){ sessionAlive=false; } if(!sessionAlive) showAuthScreen('login','Your session has expired. Please sign in again.'); } throw new Error(data.detail || 'Request failed'); } if(path==='/api/assistant'){ state.liveRecords=Object.fromEntries((data.results||[]).filter(x=>x.type==='live_chemical').map(x=>[x.id,x])); state.currentAssistantChemical=(data.results||[]).find(x=>x.type==='live_chemical')||null; } return data; };
let authMode = 'login';
function showAuthScreen(mode='login', message=''){ authMode=mode; document.body.classList.add('auth-open'); const shellEl=$('#app-shell'); if(!shellEl)return; const registering=mode==='register'; shellEl.innerHTML=`<main class="auth-screen"><section class="auth-card"><div class="auth-value-panel"><div class="brand auth-brand"><div class="brand-mark">⌬</div><div><strong>ChemR&amp;D</strong><span>Intelligence platform</span></div></div><div class="auth-eyebrow">PRIVATE R&amp;D WORKSPACE</div><h1>Research with your chemistry in one place.</h1><p class="auth-value-intro">Connect chemical identity, experiments, evidence, simulations, and team knowledge in one protected workspace.</p><div class="auth-value-list"><div><span>⬡</span><p><b>Traceable chemical records</b><small>Structures, properties, sources, and provenance stay connected.</small></p></div><div><span>◌</span><p><b>Experiment-ready workflows</b><small>Configure conditions, run simulations, and keep the full history.</small></p></div><div><span>✦</span><p><b>Clearer research decisions</b><small>Compare properties, inspect structures, and ask the research assistant.</small></p></div></div></div><div class="auth-form-panel"><div class="auth-eyebrow">${registering?'GET STARTED':'WELCOME BACK'}</div><h2>${registering?'Create your account':'Sign in to your workspace'}</h2><p class="auth-sub">${registering?'Create an account to keep your research workspace and library protected.':'Continue to your chemistry and materials workspace.'}</p><div class="auth-tabs"><button class="auth-tab ${registering?'':'active'}" onclick="showAuthScreen('login')">Sign in</button><button class="auth-tab ${registering?'active':''}" onclick="showAuthScreen('register')">Register</button></div><form onsubmit="submitAuth(event)"><label class="auth-field">Username<input id="auth-username" autocomplete="username" required minlength="3" maxlength="80" autofocus></label><label class="auth-field">Password<input id="auth-password" type="password" autocomplete="${registering?'new-password':'current-password'}" required minlength="${registering?'8':'1'}" maxlength="256"></label>${registering?'<label class="auth-field">Confirm password<input id="auth-confirm-password" type="password" autocomplete="new-password" required minlength="8" maxlength="256"></label>':''}<div id="auth-error" class="auth-error">${esc(message)}</div><button class="btn primary auth-submit" type="submit">${registering?'Create account':'Sign in'}</button></form><small class="auth-security">Passwords are stored as salted, one-way hashes. Your session is protected by an HttpOnly cookie.</small></div></section></main>`; requestAnimationFrame(fitAuthCard); }
async function submitAuth(event){ event.preventDefault(); const username=$('#auth-username').value.trim(),password=$('#auth-password').value; const error=$('#auth-error'); if(authMode==='register'&&password!==$('#auth-confirm-password').value){ error.textContent='Passwords do not match'; return; } const endpoint=authMode==='register'?'/api/auth/register':'/api/auth/login'; try{ const result=await api(endpoint,{method:'POST',body:JSON.stringify({username,password})}); authToken=result.session_token||''; try{ if(authToken) sessionStorage.setItem('chemrd_session_token',authToken); }catch(_){} window.location.reload(); }catch(e){ error.textContent=e.message; } }
async function logoutApp(){ try{ await api('/api/auth/logout',{method:'POST'}); } finally { authToken=''; try{ sessionStorage.removeItem('chemrd_session_token'); }catch(_){} window.location.reload(); } }
function applyUser(user){ state.user=user; document.body.classList.remove('auth-open'); const display=user?.username||'Researcher'; document.querySelectorAll('.user-chip b').forEach(el=>el.textContent=display); document.querySelectorAll('.user-chip small').forEach(el=>el.textContent='Authenticated user'); document.querySelectorAll('.avatar.small').forEach(el=>el.textContent=display.slice(0,2).toUpperCase()); document.querySelectorAll('.user-chip .avatar').forEach(el=>el.textContent=display.slice(0,2).toUpperCase()); }
async function initAuth(){ try{ const result=await api('/api/auth/me'); authToken=result.session_token||authToken; try{ if(authToken) sessionStorage.setItem('chemrd_session_token',authToken); }catch(_){} applyUser(result.user); render(); }catch(_){ showAuthScreen('login'); } }
const toast = (msg) => { const el=$('#toast'); el.textContent=msg; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); };

// App-wide zoom for the native desktop build and the browser fallback. CSS
// zoom scales the whole workspace together, including the sidebar, dialogs,
// charts, and internal source browser. Keep it separate from chart controls
// and store the preference locally so it survives relaunches.
const APP_ZOOM_STORAGE_KEY = 'chemrd.appZoom.v2';
const APP_ZOOM_DEFAULT = 1.5;
const APP_ZOOM_MIN = 0.5;
const APP_ZOOM_MAX = 2.0;
const APP_ZOOM_STEP = 0.1;
function applyAppZoom(value, announce=false){
  const zoom = Math.min(APP_ZOOM_MAX, Math.max(APP_ZOOM_MIN, Math.round(value * 10) / 10));
  state.appZoom = zoom;
  document.body.style.zoom = `${Math.round(zoom * 100)}%`;
  document.body.dataset.appZoom = String(zoom);
  try { localStorage.setItem(APP_ZOOM_STORAGE_KEY, String(zoom)); } catch (_) { /* storage may be disabled */ }
  if(announce) toast(`App zoom: ${Math.round(zoom * 100)}%`);
}
function initAppZoom(){
  let saved = APP_ZOOM_DEFAULT;
  try { saved = Number(localStorage.getItem(APP_ZOOM_STORAGE_KEY)) || APP_ZOOM_DEFAULT; } catch (_) { /* use the default */ }
  applyAppZoom(saved);
  document.addEventListener('keydown', event => {
    if(!event.ctrlKey || event.altKey || event.metaKey) return;
    if(event.key === '+' || event.key === '='){
      event.preventDefault();
      applyAppZoom((state.appZoom || 1) + APP_ZOOM_STEP, true);
    } else if(event.key === '-' || event.key === '_'){
      event.preventDefault();
      applyAppZoom((state.appZoom || 1) - APP_ZOOM_STEP, true);
    } else if(event.key === '0'){
      event.preventDefault();
      applyAppZoom(APP_ZOOM_DEFAULT, true);
    }
  });
}
const tag = (origin) => `<span class="tag ${origin}">${esc(origin.replaceAll('_',' '))}</span>`;

function shell(title){ $('#crumb').textContent=title; document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view)); }
function header(eyebrow,title,sub,action=''){ return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`; }
function cleanOverviewActivity(){ const heading=document.querySelector('.page-heading h1'); if(heading&&heading.textContent==='Good morning, Anika') heading.textContent='Workspace overview'; const list=document.querySelector('.activity-list'); if(list) list.innerHTML='<div class="empty">No activity yet. Save a chemical, import a source, or create an experiment to begin.</div>'; }
function cleanEmptyGraph(){ if(state.graph&&!state.graph.nodes.length){ const canvas=document.querySelector('.graph-canvas'); if(canvas) canvas.innerHTML='<div class="empty">No linked knowledge yet. Save chemicals, sources, experiments, or reactions to build the graph.</div>'; } }

async function render(){
  const view=$('#view'); view.innerHTML='<div class="empty">Loading workspace…</div>';
  try {
    if(state.view==='overview') { await overview(); cleanOverviewActivity(); }
    if(state.view==='search') searchView();
    if(state.view==='chemicals') await chemicalsView();
    if(state.view==='experiments') { await experimentsView(); const newExperimentButton=document.querySelector('.page-heading .btn.primary'); if(newExperimentButton) newExperimentButton.onclick=()=>window.openNewExperimentWizard(); }
    if(state.view==='analytics') await analyticsView();
    if(state.view==='graph') { await graphView(); cleanEmptyGraph(); }
    if(state.view==='assistant') assistantView();
    if(state.view==='ingestion') await ingestionView();
    if(state.view==='settings') await settingsView();
  } catch(e) { view.innerHTML=`<div class="panel empty">Could not load this workspace view. ${esc(e.message)}</div>`; }
}

async function overview(){
  shell('Overview'); state.dashboard ||= await api('/api/dashboard'); const d=state.dashboard; const counts=d.counts;
  const origins=d.origin_counts; const total=origins.reduce((a,b)=>a+b.count,0)||1; const colors={measured:'#67e8b4',literature_extracted:'#fbbf70',calculated:'#a9a8ff',model_predicted:'#f6a6d8',ai_estimated:'#53b5ff'};
  $('#view').innerHTML=header('WORKSPACE PULSE','Good morning, Anika','A provenance-aware view of your chemistry and materials R&D program.','<button class="btn primary" onclick="navigate(\'search\')">⌕ Search research</button>')+
    `<div class="stat-grid"><div class="stat-card" style="--glow:rgba(83,181,255,.11);--icon:#53b5ff"><div class="stat-top">Chemical records <span class="stat-icon">⬡</span></div><div class="stat-value">${counts.chemicals}</div><div class="stat-meta"><em>+12%</em> from last review</div></div><div class="stat-card" style="--glow:rgba(103,232,180,.1);--icon:#67e8b4"><div class="stat-top">Active experiments <span class="stat-icon">◌</span></div><div class="stat-value">${counts.experiments}</div><div class="stat-meta"><em>${counts.experiments-1} with recent data</em></div></div><div class="stat-card" style="--glow:rgba(251,191,112,.1);--icon:#fbbf70"><div class="stat-top">Source records <span class="stat-icon">▤</span></div><div class="stat-value">${counts.sources}</div><div class="stat-meta">${counts.sources} license-aware references</div></div><div class="stat-card" style="--glow:rgba(246,166,216,.1);--icon:#f6a6d8"><div class="stat-top">Analytical datasets <span class="stat-icon">⌁</span></div><div class="stat-value">${counts.analyses}</div><div class="stat-meta"><em>5 techniques</em> supported</div></div></div>`+
    `<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Evidence ledger</div><div class="panel-sub">Every value remains linked to its origin.</div></div><button class="text-link" onclick="navigate('chemicals')">Explore library →</button></div><div class="origin-bar">${origins.map(x=>`<i style="width:${x.count/total*100}%;background:${colors[x.origin]||'#53b5ff'}"></i>`).join('')}</div><div class="origin-legend">${origins.map(x=>`<span style="--c:${colors[x.origin]||'#53b5ff'}">${x.origin.replaceAll('_',' ')} <b>${x.count}</b></span>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Recent activity</div><div class="panel-sub">Across your pilot workspace</div></div></div><div class="activity-list"><div class="activity"><i class="activity-dot"></i><div><b>TGA/DTG profile updated</b><small>FR-Resole Pilot 01 · 18 min ago</small></div></div><div class="activity"><i class="activity-dot"></i><div><b>DOPO source linked to reaction</b><small>Patent record · yesterday</small></div></div><div class="activity"><i class="activity-dot"></i><div><b>Compatibility estimate flagged</b><small>Boric acid · needs validation</small></div></div></div></div></div>`+
    `<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Featured chemical records</div><div class="panel-sub">Identity, properties, and structure at a glance</div></div><button class="text-link" onclick="navigate('chemicals')">View all →</button></div><div class="chem-mini-grid">${d.featured_chemicals.map(c=>`<div class="chem-mini" onclick="showChemical('${c.id}')"><div class="chem-thumb">${chemicalThumbnail(c)}</div><div><b>${esc(c.name)}</b><small>${esc(c.formula||'formula pending')}</small></div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Latest source records</div><div class="panel-sub">Traceable references used in this workspace</div></div><button class="text-link" onclick="navigate('ingestion')">Manage →</button></div><div class="source-list">${d.recent_sources.slice(0,3).map(s=>`<div class="source-row"><div class="source-type">${s.source_type==='paper'?'▤':s.source_type==='patent'?'◈':'◌'}</div><div><b>${esc(s.title)}</b><small>${esc(s.publisher||'Internal')}</small></div><time>${s.license.split(' ')[0]}</time></div>`).join('')}</div></div></div>`;
}

function chemicalThumbnail(c){ const fallback=String(c.structure_svg||'').includes('No concrete structure')||!c.smiles; if(!fallback)return c.structure_svg||''; const url='/api/live-structure/2d?name='+encodeURIComponent(c.name||''); return `<img class="structure-image" src="${esc(url)}" alt="2D structure of ${esc(c.name||'chemical')}" onerror="recoverStructureImage(this)"><div class="structure-fallback" hidden><b>Structure not resolved</b><small>Open the record and search by CAS number or another exact name.</small></div>`; }
function searchView(){ shell('Universal search'); $('#view').innerHTML=header('DISCOVERY','Find across your research','Search the local workspace and structured public chemistry and literature sources.')+`<div class="search-hero"><h1>What are you investigating?</h1><p>Try a compound, identifier, DOI, research phrase, or materials question.</p><div class="search-box"><span style="padding:9px 4px 9px 10px;color:#6e859b">⌕</span><input id="search-input" placeholder="Search the research graph or public sources…" onkeydown="if(event.key==='Enter') runSearch()"/><button onclick="runSearch()">Search</button></div><label class="live-toggle"><input id="live-search" type="checkbox" checked/> Search structured public APIs live <span>ChEBI · ChEMBL · PubChem · OPSIN · NCI fallback · OpenAlex · Crossref · Europe PMC</span></label></div><div id="search-results"></div>`; }
function resultCard(r){ const isLive=r.type?.startsWith('live_'); const type=isLive?r.type.replace('live_','live '):r.type; const body=`<span class="tag">${esc(type)}</span><h3 style="margin:10px 0 0;font-size:13px">${esc(r.name)}</h3><small>${esc(r.subtitle||'')}</small><span style="color:#6e859b;font-size:10px">${esc(r.formula||r.source?.publisher||'')}</span>`; if(r.type==='live_chemical') return `<div class="result-card live-chemical-card" onclick="openLiveChemical('${esc(r.id)}')">${body}<div class="live-chemical-summary"><span>${esc(r.formula||'Formula pending')}</span><span>${r.molecular_weight?esc(r.molecular_weight)+' g/mol':'Molecular weight pending'}</span><span>${esc(r.source?.publisher||'Structured chemistry source')}</span></div><div class="result-actions"><button class="btn primary" onclick="event.stopPropagation();openLiveChemical('${esc(r.id)}')">Open chemical record</button><button class="btn ghost" onclick="event.stopPropagation();openSaveChemical('${esc(r.id)}')">＋ Save to library</button>${r.source_url?`<button class="text-link" data-url="${esc(r.source_url)}" data-title="${esc(r.name)}" onclick="event.stopPropagation();openSourcePreview(this.dataset.url,this.dataset.title)">Source record ↗</button>`:''}</div></div>`; if(r.type==='chemical' && !isLive) return `<div class="result-card" onclick="showChemical('${esc(r.id)}')">${body}<div class="result-actions"><button class="btn ghost" onclick="event.stopPropagation();openSaveLocalChemical('${esc(r.id)}','${esc(r.name)}')">＋ Save to folder</button></div></div>`; if(r.source_url) return `<div class="result-card" data-url="${esc(r.source_url)}" data-title="${esc(r.name)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">${body}<small style="color:#53b5ff">Open in internal browser ↗</small></div>`; return `<div class="result-card" onclick="toast('This record is available in the workspace graph')">${body}</div>`; }

function livePropertyTable(c){ const props=c.properties||[]; if(!props.length) return '<div class="empty">No structured properties were returned for this record.</div>'; return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Property</th><th>Value</th><th>Origin</th></tr></thead><tbody>${props.map(p=>`<tr><td><b>${esc(p.label||p.property_name||'Property')}</b></td><td>${esc(p.value)} ${esc(p.unit||'')}</td><td><span class="tag ${p.origin==='calculated'?'calculated':''}">${esc((p.origin||'source').replaceAll('_',' '))}</span></td></tr>`).join('')}</tbody></table></div>`; }
function liveChemicalLinks(c){ const links=c.source_links||{}; return `<div class="source-list live-source-list">${links.chebi?`<div class="source-row"><div class="source-type">C</div><div><b>ChEBI curated identity record</b><small>Preferred name, synonyms, identifiers, and structure</small></div><button class="text-link" data-url="${esc(links.chebi)}" data-title="${esc(c.name)} · ChEBI" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button></div>`:''}${links.chembl?`<div class="source-row"><div class="source-type">B</div><div><b>ChEMBL bioactive compound record</b><small>Drug-like compound properties and bioactivity context</small></div><button class="text-link" data-url="${esc(links.chembl)}" data-title="${esc(c.name)} · ChEMBL" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button></div>`:''}${links.pubchem?`<div class="source-row"><div class="source-type">P</div><div><b>PubChem compound record</b><small>Identity, synonyms, identifiers, and source-linked properties</small></div><button class="text-link" data-url="${esc(links.pubchem)}" data-title="${esc(c.name)} · PubChem" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button></div>`:''}${links.opsin?`<div class="source-row"><div class="source-type">O</div><div><b>OPSIN name-to-structure service</b><small>Systematic-name parsing and IUPAC enrichment</small></div><button class="text-link" data-url="${esc(links.opsin)}" data-title="${esc(c.name)} · OPSIN" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button></div>`:''}${links.cactus_fallback?`<div class="source-row"><div class="source-type">N</div><div><b>NCI resolver fallback</b><small>Used only when structured providers do not return a structure</small></div><button class="text-link" data-url="${esc(links.cactus_fallback)}" data-title="${esc(c.name)} · fallback" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button></div>`:''}</div>`; }
function openLiveChemical(id){ const raw=state.liveRecords[id]; if(!raw){ toast('Search result is no longer available; run the search again'); return; } const c=graphChemicalRecord(raw); state.currentLiveChemical=c; const cas=(c.cas_numbers||[]).join(', ')||'Not assigned'; const image=c.structure_2d_url?`<img class="structure-image" src="${esc(c.structure_2d_url)}" alt="2D structure of ${esc(c.name)}" onerror="recoverStructureImage(this)"><div class="structure-fallback" hidden><b>2D depiction unavailable</b><small>The canonical SMILES remains available below.</small></div>`:`<div class="structure-fallback"><b>2D depiction unavailable</b><small>The canonical SMILES remains available below.</small></div>`; $('#view').innerHTML=header('CHEMICAL RECORD',esc(c.name),esc(c.description)||'Structured identity, properties, and source-linked evidence.')+`<div class="chemical-overview"><div><span class="tag">${esc(c.source?.publisher||'Structured source')}</span><p class="chemical-iupac"><b>IUPAC / systematic name</b>${esc(c.iupac_name||'Not available')}</p></div><div class="header-actions"><button class="btn ghost" onclick="openSaveChemical('${esc(c.id)}')">＋ Save to library</button>${c.source_url?`<button class="btn ghost" data-url="${esc(c.source_url)}" data-title="${esc(c.name)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open source ↗</button>`:''}</div></div><div class="structure-layout"><div><div class="panel"><div class="panel-head"><div><div class="panel-title">2D structure</div><div class="panel-sub">Rendered from the resolved canonical SMILES.</div></div><span class="tag">${esc(c.identifiers?.chebi_id||'live record')}</span></div><div class="structure-art enhanced-structure-art">${image}</div><div class="structure-code"><small>Canonical SMILES</small><code>${esc(c.smiles||'Not available')}</code></div><div class="detail-meta"><div class="meta-box"><small>Formula</small><b>${esc(c.formula||'—')}</b></div><div class="meta-box"><small>Molecular weight</small><b>${c.molecular_weight?esc(c.molecular_weight)+' g/mol':'—'}</b></div><div class="meta-box"><small>CAS</small><b>${esc(cas)}</b></div><div class="meta-box"><small>InChIKey</small><b>${esc(c.inchikey||'Not assigned')}</b></div></div><div class="origin-note"><span>✓</span>Identity comes from a structured public record; descriptors marked calculated are computed locally from the SMILES.</div></div><div class="panel live-identifiers-panel"><div class="panel-head"><div><div class="panel-title">Identifiers &amp; synonyms</div><div class="panel-sub">Useful for searching, deduplication, and export.</div></div></div><div class="identifier-list"><div><small>InChI</small><code>${esc(c.inchi||'Not assigned')}</code></div><div><small>Synonyms</small><p>${(c.synonyms||[]).map(s=>`<span class="synonym-chip">${esc(s)}</span>`).join('')||'None returned'}</p></div></div></div></div><div><div class="panel" style="margin-bottom:17px"><div class="panel-head"><div><div class="panel-title">Interactive 3D structure</div><div class="panel-sub">Calculated 3D coordinates from the verified structure. Drag to rotate; scroll to zoom.</div></div><div class="viewer-tools"><select class="select" aria-label="3D representation" onchange="setMoleculeStyle(this.value)"><option value="ball" selected>Ball &amp; stick</option><option value="stick">Sticks</option><option value="sphere">Space fill</option></select><button class="btn ghost" onclick="resetMoleculeView()">Reset</button><button class="btn ghost" id="molecule-spin" onclick="toggleMoleculeSpin()">Spin</button><a class="text-link" href="${esc(c.conformer_3d_url||'#')}" onclick="downloadStructureSdf(event,this.href)" download>Download SDF</a></div></div><div class="viewer-3d enhanced-viewer" id="mol3d-${esc(c.id)}"><div class="viewer-loading">Loading 3D conformer…</div><div class="viewer-fallback" hidden><b>3D conformer unavailable</b><small>The 2D structure and identifiers remain available.</small></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Chemical property ledger</div><div class="panel-sub">Provider values and local descriptors are labeled separately.</div></div></div>${livePropertyTable(c)}</div><div class="panel"><div class="panel-head"><div><div class="panel-title">Source trail</div><div class="panel-sub">Open the original provider record when you need to verify a value.</div></div></div>${liveChemicalLinks(c)}</div></div></div>`; setTimeout(()=>setupMolViewerClean(c.smiles,c.id,c.conformer_3d_url),0); }
function openSourcePreview(url,title){ if(window.pywebview?.api?.open_source){ window.pywebview.api.open_source(url,title||'Source').catch(()=>toast('The native source window could not be opened')); return; } let reader=document.getElementById('internal-browser'); if(!reader){ document.body.insertAdjacentHTML('beforeend',`<div id="internal-browser" class="internal-browser" role="dialog" aria-modal="true" aria-label="Internal source browser"><div class="internal-browser-shell"><div class="internal-browser-toolbar"><button class="icon-button" onclick="closeSourcePreview()" aria-label="Close browser">×</button><div class="reader-title" id="reader-title">Source preview</div><div class="reader-address" id="reader-address"></div><a class="btn ghost reader-external" id="reader-external" target="_blank" rel="noreferrer">External ↗</a></div><div class="reader-status" id="reader-status">Loading source…</div><iframe id="reader-frame" title="Internal source browser" sandbox="allow-forms allow-modals allow-popups allow-presentation allow-same-origin allow-scripts"></iframe><div class="reader-footer">Some publishers block embedded previews. If a publisher blocks iframe embedding, use the native ChemR&D desktop build for a full internal source window.</div></div></div>`); reader=document.getElementById('internal-browser'); } $('#reader-title').textContent=title||'Source preview'; $('#reader-address').textContent=url; $('#reader-external').href=url; $('#reader-status').textContent='Loading source…'; $('#reader-frame').onload=()=>$('#reader-status').textContent='Source loaded · review the original page and its license'; $('#reader-frame').src=url; reader.classList.add('open'); document.body.classList.add('reader-open'); }
function closeSourcePreview(){ const reader=document.getElementById('internal-browser'); if(!reader) return; reader.classList.remove('open'); document.body.classList.remove('reader-open'); const frame=document.getElementById('reader-frame'); if(frame) frame.src='about:blank'; }
async function runSearch(){ const q=$('#search-input').value.trim(); if(!q) return; const live=$('#live-search')?.checked ?? true; const data=await api('/api/search?q='+encodeURIComponent(q)+'&live='+live); state.results=data.results; state.liveRecords=Object.fromEntries(data.results.filter(r=>r.type==='live_chemical').map(r=>[r.id,r])); const liveCount=data.live?.results?.length||0; $('#search-results').innerHTML=`<div class="panel-head"><div><div class="panel-title">${data.results.length} results for “${esc(q)}”</div><div class="panel-sub">${live?`Live retrieval returned ${liveCount} public-source matches.`:'Local workspace records only.'}</div></div></div>${data.results.length?`<div class="result-grid">${data.results.map(resultCard).join('')}</div>`:'<div class="panel empty">No matching records. Try a broader term or enable live public-source search.</div>'}`; }

function libraryItemTypeLabel(item){ return item.item_type==='chemical'?'chemical record':item.item_type; }
function libraryItemsHtml(items){ if(!items.length) return '<div class="empty">Nothing saved in this folder yet.</div>'; return items.map(item=>`<div class="library-item"><div><span class="tag">${esc(libraryItemTypeLabel(item))}</span><b>${esc(item.title)}</b><small>${esc(item.chemical_name||item.source_title||item.content||'')}</small></div><div>${item.url?`<button class="text-link" data-url="${esc(item.url)}" data-title="${esc(item.title)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button>`:''}</div></div>`).join(''); }
async function selectLibraryFolder(id){ state.libraryFolderId=id; await chemicalsView(); }
async function openNewLibraryFolder(){ const name=window.prompt('Folder name'); if(!name?.trim()) return; const description=window.prompt('What is this folder for?')||''; try { await api('/api/library/folders',{method:'POST',body:JSON.stringify({name,description})}); toast('Folder created'); await chemicalsView(); } catch(e){ toast(e.message); } }
function openSaveChemical(id){ const record=state.liveRecords[id]; if(!record){ toast('Search result is no longer available; run the search again'); return; } openFolderPicker({kind:'live_chemical',record}).catch(e=>toast(e.message)); }
function openSaveLocalChemical(id,title){ openFolderPicker({kind:'local_chemical',chemical_id:id,title}).catch(e=>toast(e.message)); }
function openNewLibraryItem(){ openFolderPicker({kind:'generic'}).catch(e=>toast(e.message)); }
async function openFolderPicker(pending){ state.pendingLibraryItem=pending; const folders=await api('/api/library/folders'); const fields=pending.kind==='generic'?`<label class="library-field">Type<select id="library-item-type"><option value="website">Website</option><option value="paper">Paper</option><option value="patent">Patent</option><option value="note">Note</option><option value="experiment">Experiment</option><option value="file">File</option><option value="other">Other</option></select></label><label class="library-field">Title<input id="library-item-title" placeholder="What are you saving?"/></label><label class="library-field">URL<input id="library-item-url" placeholder="https://…"/></label><label class="library-field">Notes<textarea id="library-item-content" placeholder="Optional notes"></textarea></label>`:''; document.getElementById('library-modal')?.remove(); document.body.insertAdjacentHTML('beforeend',`<div id="library-modal" class="library-modal"><div class="library-modal-card"><div class="panel-head"><div><div class="panel-title">${pending.kind==='generic'?'Add to chemical library':'Save to chemical library'}</div><div class="panel-sub">Choose a folder. You can move or reuse this item later.</div></div><button class="icon-button" onclick="closeLibraryModal()">×</button></div><label class="library-field">Folder<select id="library-folder-select">${folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)} · ${f.item_count} items</option>`).join('')}</select></label>${fields}<div class="library-modal-actions"><button class="btn ghost" onclick="openNewLibraryFolderFromPicker()">＋ New folder</button><span></span><button class="btn ghost" onclick="closeLibraryModal()">Cancel</button><button class="btn primary" onclick="confirmFolderSave()">Save</button></div></div></div>`); }
async function openNewLibraryFolderFromPicker(){ const name=window.prompt('Folder name'); if(!name?.trim()) return; const description=window.prompt('What is this folder for?')||''; try { await api('/api/library/folders',{method:'POST',body:JSON.stringify({name,description})}); const pending=state.pendingLibraryItem; await openFolderPicker(pending); } catch(e){ toast(e.message); } }
function closeLibraryModal(){ document.getElementById('library-modal')?.remove(); state.pendingLibraryItem=null; }
async function confirmFolderSave(){ const pending=state.pendingLibraryItem; const folder_id=$('#library-folder-select')?.value; if(!pending||!folder_id) return; try { let result; if(pending.kind==='live_chemical') result=await api('/api/library/chemicals',{method:'POST',body:JSON.stringify({folder_id,record:pending.record})}); else if(pending.kind==='local_chemical') result=await api('/api/library/items',{method:'POST',body:JSON.stringify({folder_id,item_type:'chemical',title:pending.title,chemical_id:pending.chemical_id})}); else result=await api('/api/library/items',{method:'POST',body:JSON.stringify({folder_id,item_type:$('#library-item-type').value,title:$('#library-item-title').value,url:$('#library-item-url').value,content:$('#library-item-content').value})}); closeLibraryModal(); toast(`Saved to ${result.folder_name||'chemical library'}`); if(state.view==='chemicals') await chemicalsView(); } catch(e){ toast(e.message); } }
async function chemicalsView(){
  shell('Chemical library');
  const data=state.chemicals.length?state.chemicals:(state.chemicals=await api('/api/chemicals'));
  const folders=await api('/api/library/folders'); state.libraryFolders=folders;
  if(!state.libraryFolderId||!folders.some(f=>f.id===state.libraryFolderId)) state.libraryFolderId=folders[0]?.id||null;
  const items=state.libraryFolderId?await api('/api/library/folders/'+encodeURIComponent(state.libraryFolderId)+'/items'):[];
  const selected=folders.find(f=>f.id===state.libraryFolderId);
  const folderCards=folders.map(f=>`<button class="library-folder ${f.id===state.libraryFolderId?'active':''}" onclick="selectLibraryFolder('${esc(f.id)}')"><b>${esc(f.name)}</b><small>${f.item_count} saved items</small></button>`).join('');
  const chemicalRows=data.map(c=>`<tr onclick="showChemical('${esc(c.id)}')" style="cursor:pointer"><td><b>${esc(c.name)}</b><br><span style="font-size:10px;color:#71879b">${esc(c.synonyms?.[0]||'')}</span></td><td>${esc(c.formula||'—')}</td><td>${esc(c.cas_number||c.id)}</td><td><div class="chem-thumb">${chemicalThumbnail(c)}</div></td><td><button class="btn ghost" onclick="event.stopPropagation();openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save</button></td></tr>`).join('');
  $('#view').innerHTML=header('CHEMISTRY GRAPH','Chemical library','Canonical chemical records plus folders for papers, websites, notes, patents, experiments, and other research material.',`<div class="header-actions"><button class="btn ghost" onclick="openNewLibraryFolder()">＋ New folder</button><button class="btn primary" onclick="openNewLibraryItem()">＋ Add research item</button></div>`)+`<div class="library-folder-strip">${folderCards}</div><div class="panel library-items-panel"><div class="panel-head"><div><div class="panel-title">${esc(selected?.name||'Library items')}</div><div class="panel-sub">${esc(selected?.description||'Choose a folder to see saved research.')}</div></div></div>${libraryItemsHtml(items)}</div><div class="panel"><div class="panel-head"><div><div class="panel-title">${data.length} canonical chemical records</div><div class="panel-sub">Select a record to inspect structure and provenance.</div></div><input class="select" placeholder="Filter records…" oninput="filterTable(this.value)" style="width:190px"/></div><div class="table-wrap"><table class="data-table" id="chem-table"><thead><tr><th>Record</th><th>Formula</th><th>CAS / ID</th><th>Structure</th><th>Save</th></tr></thead><tbody>${chemicalRows}</tbody></table></div></div>`;
}
function filterTable(q){ document.querySelectorAll('#chem-table tbody tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q.toLowerCase())?'':'none'); }
function ensureChemicalSaveButton(){ const head=document.querySelector('.structure-layout .panel .panel-head'); const c=state.currentChemical; if(!head||!c||head.querySelector('.chemical-save-button')) return; head.insertAdjacentHTML('beforeend',`<button class="btn ghost chemical-save-button" onclick="openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save to folder</button>`); }

function chemicalPropertiesTable(c){ const props=(c.properties||[]); if(!props.length) return '<div class="empty">No source-linked properties have been saved for this record yet.</div>'; return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Property</th><th>Value</th><th>Origin</th><th>Source</th></tr></thead><tbody>${props.map(p=>`<tr><td><b>${esc(p.property_name.replaceAll('_',' '))}</b><br><small style="color:#6f8599">${esc(p.method||'method not specified')}</small></td><td>${esc(p.value_text)} ${esc(p.unit||'')}</td><td>${tag(p.origin)}</td><td><small>${esc(p.source_title||'No source link')}</small></td></tr>`).join('')}</tbody></table></div>`; }
function moleculeStyleObject(style){ if(style==='sphere') return {sphere:{scale:0.34,colorscheme:'Jmol'}}; if(style==='stick') return {stick:{radius:0.16,colorscheme:'Jmol'}}; return {stick:{radius:0.16,colorscheme:'Jmol'},sphere:{scale:0.24,colorscheme:'Jmol'}}; }
function setMoleculeStyle(style){ const item=state.moleculeViewer; if(!item?.viewer)return; item.style=style; item.viewer.setStyle({},moleculeStyleObject(style)); item.viewer.render(); }
function resetMoleculeView(){ const item=state.moleculeViewer; if(!item?.viewer)return; item.viewer.zoomTo(); item.viewer.render(); }
function toggleMoleculeSpin(){ const item=state.moleculeViewer; if(!item?.viewer)return; item.spinning=!item.spinning; item.viewer.spin(item.spinning?'y':false,0.18); const button=$('#molecule-spin'); if(button) button.textContent=item.spinning?'Stop spin':'Spin'; }
async function showChemicalClean(id){ const c=await api('/api/chemicals/'+id); state.currentChemical=c; const iupac=c.properties?.find(p=>p.property_name==='iupac_name')?.value_text || c.description || ''; const image=c.structure_2d_url?`<img class="structure-image" src="${esc(c.structure_2d_url)}" alt="2D structure of ${esc(c.name)}" onerror="recoverStructureImage(this)"><div class="structure-fallback" hidden><b>2D depiction unavailable</b><small>Use the canonical SMILES below or retry when the public structure service is available.</small></div>`:`<div class="structure-fallback"><b>2D depiction unavailable</b><small>Use the canonical SMILES below.</small></div>`; $('#view').innerHTML=header('CHEMICAL RECORD',c.name,'Identity, structure, and source-linked evidence.')+`<div class="chemical-overview"><div><span class="tag">${esc(c.id)}</span><p class="chemical-iupac"><b>IUPAC name</b>${esc(iupac||'Not available')}</p></div><button class="btn ghost" onclick="openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save to folder</button></div><div class="structure-layout"><div><div class="panel"><div class="panel-head"><div><div class="panel-title">2D structure</div><div class="panel-sub">Generated locally from the verified molecular structure.</div></div></div><div class="structure-art enhanced-structure-art">${image}</div><div class="structure-code"><small>Canonical SMILES</small><code>${esc(c.smiles||'Not available')}</code></div><div class="detail-meta"><div class="meta-box"><small>Formula</small><b>${esc(c.formula||'—')}</b></div><div class="meta-box"><small>Molecular weight</small><b>${c.molecular_weight?c.molecular_weight+' g/mol':'—'}</b></div><div class="meta-box"><small>CAS</small><b>${esc(c.cas_number||'Not assigned')}</b></div><div class="meta-box"><small>InChIKey</small><b>${esc(c.inchikey||'Not assigned')}</b></div></div><div class="origin-note"><span>✓</span>Identity and structure are kept separate from measured or calculated properties.</div></div></div><div><div class="panel" style="margin-bottom:17px"><div class="panel-head"><div><div class="panel-title">Interactive 3D conformer</div><div class="panel-sub">Calculated 3D conformer; not an experimental crystal structure.</div></div><div class="viewer-tools"><select class="select" aria-label="3D representation" onchange="setMoleculeStyle(this.value)"><option value="ball" selected>Ball &amp; stick</option><option value="stick">Sticks</option><option value="sphere">Space fill</option></select><button class="btn ghost" onclick="resetMoleculeView()">Reset</button><button class="btn ghost" id="molecule-spin" onclick="toggleMoleculeSpin()">Spin</button><a class="text-link" href="${esc(c.conformer_3d_url||'#')}" onclick="downloadStructureSdf(event,this.href)" download>Download SDF</a></div></div><div class="viewer-3d enhanced-viewer" id="mol3d-${esc(c.id)}"><div class="viewer-loading">Loading 3D conformer…</div><div class="viewer-fallback" hidden><b>3D conformer unavailable</b><small>The 2D structure and canonical SMILES remain available. Check the source connection and try again.</small></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Property ledger</div><div class="panel-sub">Every value retains its origin and source.</div></div></div>${chemicalPropertiesTable(c)}</div></div></div>`; setTimeout(()=>setupMolViewerClean(c.smiles,c.id,c.conformer_3d_url),0); }
async function experimentsView(){ shell('Experiments'); const [experiments, forms, reactions, simulations]=await Promise.all([api('/api/experiments'),api('/api/formulations'),api('/api/reactions'),api('/api/simulations')]); const history=simulations.length?`<div class="panel simulation-history-panel"><div class="panel-head"><div><div class="panel-title">Simulation history</div><div class="panel-sub">Completed simulations are saved to your account and can be reopened or downloaded.</div></div><span class="tag">${simulations.length} saved</span></div><div class="simulation-history-list">${simulations.map(s=>`<div class="simulation-history-row"><div class="simulation-history-main"><b>${esc(s.name)}</b><small>${esc(s.reaction_type||s.experiment_type||'Simulation')} · ${s.feasibility_score==null?'Feasibility pending':`${s.feasibility_score}% feasibility`} · ${esc(s.main_product||'Product not specified')}</small><time>${esc(new Date(s.created_at).toLocaleString())}</time></div><div class="simulation-history-actions"><button class="btn ghost mini" onclick="openSavedSimulation('${esc(s.id)}')">Open details</button><button class="btn ghost mini" onclick="downloadSavedSimulationCSV('${esc(s.id)}')">CSV</button><button class="btn ghost mini" onclick="downloadSavedSimulation('${esc(s.id)}')">JSON</button></div></div>`).join('')}</div></div>`:'<div class="panel simulation-history-panel"><div class="panel-title">Simulation history</div><div class="panel-sub">Run a simulation to create your first saved result.</div></div>'; $('#view').innerHTML=header('R&D OPERATIONS','Experiments & process records','Keep objectives, formulations, reaction conditions, and analytical follow-up connected.','<button class="btn primary" onclick="window.openNewExperimentWizard()">＋ New experiment</button>')+`<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Experiment register</div><div class="panel-sub">${experiments.length} records in the pilot workspace.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Experiment</th><th>Status</th><th>Owner</th><th>Materials</th></tr></thead><tbody>${experiments.map(e=>`<tr><td><b>${esc(e.name)}</b><br><small style="color:#71869b">${esc(e.objective)}</small></td><td><span class="status ${e.status}">${esc(e.status.replace('_',' '))}</span></td><td>${esc(e.owner)}</td><td>${e.chemical_ids.length} linked</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Formulations</div><div class="panel-sub">Composition is versionable and source-linked.</div></div></div>${forms.map(f=>`<div class="source-row"><div class="source-type">⚗</div><div><b>${esc(f.name)}</b><small>${esc(f.purpose)}</small></div><span class="status">${esc(f.status)}</span></div>`).join('')}</div></div>`+history+`<div class="panel"><div class="panel-head"><div><div class="panel-title">Reaction & process records</div><div class="panel-sub">Inputs, outputs, conditions, and yield are separate from property evidence.</div></div></div><div class="result-grid">${reactions.map(r=>`<div class="result-card"><span class="tag">${esc(r.reaction_type)}</span><h3 style="margin:10px 0 4px;font-size:13px">${esc(r.name)}</h3><small>${Object.entries(r.conditions).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join(' · ')}</small><div style="color:#70dcb9;font-size:11px;margin-top:10px">${esc(r.yield_text||'yield not recorded')}</div></div>`).join('')}</div></div>`; }

function propertyChartSvg(catalog,xKey,yKey){ const xm=catalog.metrics.find(m=>m.key===xKey),ym=catalog.metrics.find(m=>m.key===yKey); if(!xm||!ym) return '<div class="empty">Choose an X and Y metric to draw the comparison.</div>'; const points=catalog.points.map(p=>{const x=p.values?.[xKey],y=p.values?.[yKey]; return x&&y&&Number.isFinite(Number(x.value))&&Number.isFinite(Number(y.value))?{name:p.name,x:Number(x.value),y:Number(y.value),xs:x,ys:y}:null}).filter(Boolean); if(!points.length) return `<div class="empty">No chemicals currently have both “${esc(xm.label)}” and “${esc(ym.label)}”. Add numeric property evidence with matching metrics to plot them.</div>`; const W=820,H=360,pad={l:64,r:24,t:24,b:54},xs=points.map(p=>p.x),ys=points.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xpad=(xmax-xmin||1)*.12,ypad=(ymax-ymin||1)*.12,x0=xmin-xpad,x1=xmax+xpad,y0=ymin-ypad,y1=ymax+ypad,X=v=>pad.l+(v-x0)/(x1-x0||1)*(W-pad.l-pad.r),Y=v=>H-pad.b-(v-y0)/(y1-y0||1)*(H-pad.t-pad.b); return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(ym.label)} versus ${esc(xm.label)}"><g stroke="#1b3449" stroke-width="1">${[0,1,2,3,4].map(i=>`<line x1="${pad.l}" x2="${W-pad.r}" y1="${pad.t+i*(H-pad.t-pad.b)/4}" y2="${pad.t+i*(H-pad.t-pad.b)/4}"/>`).join('')}</g><g fill="#9ab0c2" font-size="10"><text x="${pad.l}" y="${H-12}">${x0.toFixed(2)}</text><text x="${W-pad.r-36}" y="${H-12}">${x1.toFixed(2)}</text><text x="8" y="${H-pad.b}">${y0.toFixed(2)}</text><text x="8" y="${pad.t+5}">${y1.toFixed(2)}</text><text x="${W/2}" y="${H-2}" text-anchor="middle">${esc(xm.label)}${xm.unit?' · '+esc(xm.unit):''}</text><text x="14" y="${H/2}" text-anchor="middle" transform="rotate(-90 14 ${H/2})">${esc(ym.label)}${ym.unit?' · '+esc(ym.unit):''}</text></g>${points.map(pt=>`<circle cx="${X(pt.x).toFixed(1)}" cy="${Y(pt.y).toFixed(1)}" r="6" fill="#53b5ff" stroke="#dbeafe" stroke-width="1.5"><title>${esc(pt.name)} · X ${pt.x} ${esc(pt.xs.unit||'')} · Y ${pt.y} ${esc(pt.ys.unit||'')} · ${esc(pt.ys.origin)}</title></circle>`).join('')}</svg>`; }
function renderPropertyComparison(catalog){ state.propertyCatalog=catalog; const metrics=catalog.metrics||[]; if(metrics.length<2) return '<div class="panel empty">No two numeric chemical metrics are available yet. Add chemical property evidence to enable X-versus-Y plots.</div>'; const xKey=state.propertyX&&metrics.some(m=>m.key===state.propertyX)?state.propertyX:metrics[0].key, yKey=state.propertyY&&metrics.some(m=>m.key===state.propertyY)?state.propertyY:(metrics.find(m=>m.key!==xKey)?.key||metrics[0].key); state.propertyX=xKey; state.propertyY=yKey; const options=(selected)=>metrics.map(m=>`<option value="${esc(m.key)}" ${m.key===selected?'selected':''}>${esc(m.label)}${m.unit?' · '+esc(m.unit):''}</option>`).join(''); return `<div class="panel property-comparison-panel"><div class="panel-head"><div><div class="panel-title">Chemical property comparison</div><div class="panel-sub">Choose any two numeric metrics. Origins stay explicit in each selector and point tooltip.</div></div><div class="chart-controls"><label class="library-field">X axis<select class="select" id="property-x-select" onchange="updatePropertyPlot()">${options(xKey)}</select></label><label class="library-field">Y axis<select class="select" id="property-y-select" onchange="updatePropertyPlot()">${options(yKey)}</select></label></div></div><div class="chart-box" id="property-chart">${propertyChartSvg(catalog,xKey,yKey)}</div><div class="origin-note"><span>i</span>Only chemicals with both selected values appear. Measured, literature-extracted, calculated, predicted, and AI-estimated values are never combined under one metric.</div></div>`; }
function updatePropertyPlot(){ const x=$('#property-x-select')?.value,y=$('#property-y-select')?.value; if(!state.propertyCatalog||!x||!y)return; state.propertyX=x; state.propertyY=y; const chart=$('#property-chart'); if(chart) chart.innerHTML=propertyChartSvg(state.propertyCatalog,x,y); }
