// Secure startup gate: keep the application shell hidden until session status
// is known, then reveal either the workspace or the sign-in screen.
function finishAuthStartup(){ document.body.classList.remove('auth-checking'); const splash=$('#startup-screen'); if(splash)splash.hidden=true; }
function showAuthScreen(mode='login',message=''){
  authMode=mode;
  finishAuthStartup();
  document.body.classList.add('auth-open');
  const shellEl=$('#app-shell');
  if(!shellEl)return;
  const registering=mode==='register';
  shellEl.innerHTML=`<main class="auth-screen"><section class="auth-card"><div class="auth-value-panel"><div class="brand auth-brand"><div class="brand-mark">⌬</div><div><strong>ChemR&amp;D</strong><span>Intelligence platform</span></div></div><div class="auth-eyebrow">PRIVATE R&amp;D WORKSPACE</div><h1>Research with your chemistry in one place.</h1><p class="auth-value-intro">Connect chemical identity, experiments, evidence, simulations, and team knowledge in one protected workspace.</p><div class="auth-value-list"><div><span>⬡</span><p><b>Traceable chemical records</b><small>Structures, properties, sources, and provenance stay connected.</small></p></div><div><span>◌</span><p><b>Experiment-ready workflows</b><small>Configure conditions, run simulations, and keep the full history.</small></p></div><div><span>✦</span><p><b>Clearer research decisions</b><small>Compare properties, inspect structures, and ask the research assistant.</small></p></div></div></div><div class="auth-form-panel"><div class="auth-eyebrow">${registering?'GET STARTED':'WELCOME BACK'}</div><h2>${registering?'Create your account':'Sign in to your workspace'}</h2><p class="auth-sub">${registering?'Create an account to keep your research workspace and library protected.':'Continue to your chemistry and materials workspace.'}</p><div class="auth-tabs"><button class="auth-tab ${registering?'':'active'}" onclick="showAuthScreen('login')">Sign in</button><button class="auth-tab ${registering?'active':''}" onclick="showAuthScreen('register')">Register</button></div><form onsubmit="submitAuth(event)"><label class="auth-field">Username<input id="auth-username" autocomplete="username" required minlength="3" maxlength="80" autofocus></label><label class="auth-field">Password<input id="auth-password" type="password" autocomplete="${registering?'new-password':'current-password'}" required minlength="${registering?'8':'1'}" maxlength="256"></label>${registering?'<label class="auth-field">Confirm password<input id="auth-confirm-password" type="password" autocomplete="new-password" required minlength="8" maxlength="256"></label>':'<label class="remember-row"><input id="remember-me" type="checkbox"><span>Keep me logged in on this device</span></label>'}<div id="auth-error" class="auth-error" role="alert">${esc(message)}</div><button class="btn primary auth-submit" type="submit">${registering?'Create account':'Sign in'}</button></form><small class="auth-security">Passwords are stored as salted, one-way hashes. Your session is protected by an HttpOnly cookie.</small></div></section></main>`;
  requestAnimationFrame(fitAuthCard);
}
async function submitAuth(event){
  event.preventDefault();
  const username=$('#auth-username').value.trim(),password=$('#auth-password').value,error=$('#auth-error'),button=$('.auth-submit');
  if(authMode==='register'&&password!==$('#auth-confirm-password').value){error.textContent='Passwords do not match';return;}
  const endpoint=authMode==='register'?'/api/auth/register':'/api/auth/login';
  if(button){button.disabled=true;button.innerHTML='<span class="spinner" aria-hidden="true"></span> Signing in…';}
  try{
    const result=await api(endpoint,{method:'POST',body:JSON.stringify({username,password,remember_me:authMode==='login'&&Boolean($('#remember-me')?.checked)})});
    authToken=result.session_token||'';
    try{if(authToken)sessionStorage.setItem('chemrd_session_token',authToken);}catch(_){}
    window.location.reload();
  }catch(e){error.textContent=e.message;if(button){button.disabled=false;button.textContent=authMode==='register'?'Create account':'Sign in';}}
}
function applyUser(user){
  state.user=user;
  document.body.classList.remove('auth-open');
  const display=user?.full_name||user?.username||'Researcher', initials=(user?.username||'AR').slice(0,2).toUpperCase();
  document.querySelectorAll('.user-chip b').forEach(el=>el.textContent=display);
  document.querySelectorAll('.user-chip small').forEach(el=>el.textContent=user?.organization||'Authenticated user');
  document.querySelectorAll('.avatar.small,.user-chip .avatar').forEach(el=>{
    el.textContent=initials;
    if(user?.profile_picture){el.style.backgroundImage=`url("${user.profile_picture}")`;el.style.backgroundSize='cover';el.style.backgroundPosition='center';el.style.color='transparent';}
    else{el.style.backgroundImage='';el.style.color='';}
  });
}
async function initAuth(){
  try{
    const result=await api('/api/auth/me');authToken=result.session_token||authToken;
    try{if(authToken)sessionStorage.setItem('chemrd_session_token',authToken);}catch(_){}
    applyUser(result.user);
    try{const preferences=await api('/api/settings/preferences');state.settingsBundle={settings:preferences.settings};applyAppearance(preferences.settings);}catch(_){}
    await render();
    finishAuthStartup();
  }catch(_){showAuthScreen('login');}
}
function historyDate(value){return displayDate(value,state.settingsBundle?.settings?.appearance?.language||'system');}

// Loading feedback for the three network-heavy research actions.
async function runSearch(){
  const input=$('#search-input'),q=input?.value.trim();if(!q||state.searchBusy)return;
  const live=$('#live-search')?.checked??true,button=$('.search-box button'),host=$('#search-results');
  state.searchBusy=true;
  if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.innerHTML='<span class="spinner" aria-hidden="true"></span> Searching';}
  if(host)host.innerHTML='<div class="panel search-progress" role="status"><span class="spinner" aria-hidden="true"></span><div><b>Searching your workspace and public sources</b><small>This can take a few seconds while live chemistry and literature services respond.</small></div></div>';
  try{
    const data=await api('/api/search?q='+encodeURIComponent(q)+'&live='+live);
    state.results=data.results||[];state.liveRecords=Object.fromEntries(state.results.filter(r=>r.type==='live_chemical').map(r=>[r.id,r]));
    const liveCount=data.live?.results?.length||0;
    if(host)host.innerHTML=`<div class="panel-head"><div><div class="panel-title">${state.results.length} results for “${esc(q)}”</div><div class="panel-sub">${live?`Live retrieval returned ${liveCount} public-source matches.`:'Local workspace records only.'}</div></div></div>${state.results.length?`<div class="result-grid">${state.results.map(resultCard).join('')}</div>`:'<div class="panel empty">No matching records. Try a broader term or enable live public-source search.</div>'}`;
  }catch(e){if(host)host.innerHTML=`<div class="panel search-error" role="alert">Search could not be completed: ${esc(e.message)}. Check your connection and try again.</div>`;}
  finally{state.searchBusy=false;if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Search';}}
}
async function askAssistant(){
  const input=$('#assistant-input'),q=input?.value.trim();if(!q||state.assistantBusy)return;
  const messages=$('#chat-messages'),button=$('.chat-input button'),live=$('#assistant-live')?.checked??true;
  state.assistantBusy=true;
  messages.insertAdjacentHTML('beforeend',`<div class="message user"><div class="avatar">AR</div><div><div class="bubble">${esc(q)}</div><small>You · now</small></div></div><div class="assistant-loading" id="assistant-loading" role="status"><span class="spinner" aria-hidden="true"></span><span>Researching sources and preparing an answer…</span></div>`);
  input.value='';input.disabled=true;
  if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.innerHTML='<span class="spinner" aria-hidden="true"></span> Researching';}
  messages.scrollTop=messages.scrollHeight;
  try{
    const data=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:q,live})});
    const mode=data.assistant_mode==='llm_synthesis'?`${data.assistant_provider||'AI'} synthesis + live retrieval`:data.retrieved_at?'live retrieval summary':'workspace evidence';
    const memoryState=data.memory_enabled?(data.memory_status==='unavailable'?'unavailable':data.memory_used?'recalled':'ready'):'disabled';
    const status=(data.assistant_status||mode)+` · Hindsight ${memoryState}`;
    const answerHtml=`<div class="answer-label">Direct answer</div><div class="bubble">${assistantHtml(data.answer)}</div>`;
    const sourcesHtml=data.citations?.length?`<div class="source-label">Research sources</div>${citationHtml(data.citations)}`:'';
    $('#assistant-loading')?.remove();messages.insertAdjacentHTML('beforeend',`<div class="message"><div class="avatar">✦</div><div>${answerHtml}${sourcesHtml}<small>Assistant · ${esc(status)}</small></div></div>`);
    if(data.history_saved!==false)await loadAssistantHistory();
  }catch(e){$('#assistant-loading')?.remove();messages.insertAdjacentHTML('beforeend',`<div class="message"><div class="avatar">✦</div><div><div class="bubble">The answer could not be completed: ${esc(e.message)}. Your question may not have been saved.</div></div></div>`);}
  finally{state.assistantBusy=false;if(input)input.disabled=false;if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Ask';}if(messages)messages.scrollTop=messages.scrollHeight;}
}
async function lookupGraphChemical(){
  const input=$('#graph-chemical-query'),q=input?.value.trim();if(!q||state.graphLookupBusy)return;
  const button=$('#graph-lookup-button'),controls=$('.graph-lookup-controls');let status=$('#graph-lookup-progress');
  if(!status&&controls){status=document.createElement('div');status.id='graph-lookup-progress';status.className='search-progress graph-lookup-progress';status.setAttribute('role','status');controls.insertAdjacentElement('afterend',status);}
  state.graphLookupBusy=true;
  if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.innerHTML='<span class="spinner" aria-hidden="true"></span> Finding';}
  if(status)status.innerHTML='<span class="spinner" aria-hidden="true"></span><div><b>Looking up chemical identity and structure</b><small>Checking available structure providers…</small></div>';
  try{
    const data=await api('/api/research/live?q='+encodeURIComponent(q));
    const result=(data.results||[]).find(x=>x.type==='live_chemical');
    if(!result){if(status)status.innerHTML='<div>No structure match was returned. Try a CAS number, synonym, or systematic name.</div>';toast('No live chemical identity match found');return;}
    const chemical=graphChemicalRecord(result);state.liveRecords[chemical.id]=chemical;renderGraphChemicalInspector(chemical);
    if(status)status.innerHTML=`<span class="success-mark">✓</span><div><b>${esc(chemical.name)}</b><small>Identity loaded; structure preview is opening.</small></div>`;
  }catch(e){if(status)status.innerHTML=`<div class="search-error">Lookup failed: ${esc(e.message)}</div>`;toast(`Chemical lookup failed: ${e.message}`);}
  finally{state.graphLookupBusy=false;if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Find structure';}}
}

// Account settings UI and actions.
function displayDate(value,language){try{return new Date(value).toLocaleString(language==='system'?'default':language||'en');}catch(_){return value||'';}}
function applyAppearance(settings={}){
  const appearance=settings.appearance||{},theme=appearance.theme||'system',font=appearance.font_size||'medium';
  document.body.dataset.theme=theme;document.body.dataset.fontSize=font;
  document.documentElement.lang=appearance.language==='system'?((navigator.language||'en').split('-')[0]):(appearance.language||'en');
  state.fontScale=font==='small'?.92:font==='large'?1.08:1;
  if(typeof state.appZoom==='number')applyAppZoom(state.appZoom);
}
function applyAppZoom(value,announce=false){
  const zoom=Math.min(APP_ZOOM_MAX,Math.max(APP_ZOOM_MIN,Math.round(value*10)/10));
  state.appZoom=zoom;
  const effective=zoom*(state.fontScale||1);
  document.body.style.zoom=`${Math.round(effective*100)}%`;document.body.dataset.appZoom=String(zoom);
  try{localStorage.setItem(APP_ZOOM_STORAGE_KEY,String(zoom));}catch(_){}
  if(announce)toast(`App zoom: ${Math.round(zoom*100)}%`);
}
