async function previewProfilePicture(event){
  const file=event.target.files?.[0];if(!file)return;
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPEG, or WebP image');event.target.value='';return;}
  try{
    const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});
    const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=data;});
    const canvas=document.createElement('canvas'),ratio=Math.min(1,320/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*ratio));canvas.height=Math.max(1,Math.round(image.height*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
    const compressed=canvas.toDataURL('image/jpeg',.82);if(compressed.length>850000)throw new Error('Image is too large after compression');
    state.pendingProfilePicture=compressed;$('#settings-profile-picture').innerHTML=`<img src="${compressed}" alt="Profile picture preview">`;
  }catch(e){toast(e.message||'Could not read that image');}
}
function clearProfilePicture(){state.pendingProfilePicture='';const initial=(state.settingsBundle?.profile?.username||'AR').slice(0,2).toUpperCase();$('#settings-profile-picture').innerHTML=`<span>${esc(initial)}</span>`;}
